def _weights_bytes() -> bytes:
    return zlib.decompress(base64.b85decode(_WEIGHTS_B85))


# --- kit pipe loop + inlined fail-safe (never leave a query unanswered) -------

def _zero_move(player_id):
    return MovePlayer(player_id=player_id,
                      direction=DirectionModel(x=0.0, y=0.0), split=False)


def _flee_center(query, player_id):
    try:
        x, y = query.you.pos
        dx = spec.ARENA_SIZE / 2.0 - float(x)
        dy = spec.ARENA_SIZE / 2.0 - float(y)
        if abs(dx) > 1e-9 or abs(dy) > 1e-9:
            return MovePlayer(player_id=player_id,
                              direction=DirectionModel(x=dx, y=dy), split=False)
    except Exception:
        pass
    return _zero_move(player_id)


def main():
    conn = Connection()  # open pipes first (the engine's open-pipe alarm is live)
    policy = NumpyPolicy.load(io.BytesIO(_weights_bytes()))
    # Free the ~3 MB base85 weight literal + decode buffers before the game
    # starts — otherwise they sit resident and trip the RSS gate.
    globals().pop("_WEIGHTS_B85", None)
    gc.collect()
    gc.disable()
    featurizer = Featurizer()
    hidden = policy.initial_hidden()
    player_id = None
    turns = 0

    while True:
        try:
            raw = conn._receive()
        except EOFError:
            return
        query = None
        try:
            query = QueryMovePlayer.model_validate_json(raw)
            player_id = query.you.player_id
        except Exception:
            if player_id is None:
                try:
                    player_id = int(json.loads(raw)["you"]["player_id"])
                except Exception:
                    player_id = 0
        try:
            obs = featurizer.featurize(query)
            action, new_hidden = policy.act(obs, hidden)
            if not np.isfinite(new_hidden).all():
                new_hidden = policy.initial_hidden()
            move = ActionAdapter.to_move(player_id, action)
            if not isinstance(move, MovePlayer) or move.player_id != player_id:
                raise ValueError("invalid move")
            hidden = new_hidden
        except Exception:
            move = _flee_center(query, player_id) if query is not None \
                else _zero_move(player_id)
        conn.send_move(move)
        turns += 1
        if turns % 32 == 0:  # clear cyclic garbage post-flush (RSS-stable)
            gc.collect(0)


if __name__ == "__main__":
    main()
